        private static string BuildSubject(string pattern, params string[] namesAndValues) {
            var result = pattern;
            for (var index = 0; index < namesAndValues.Length; index += 2) {
                var name = namesAndValues[index];
                var value = namesAndValues[index + 1];
                ValidateSubjectToken(name, value);
                result = result.Replace("{" + name + "}", value);
            }
            return result;
        }

        private static void ValidateSubjectToken(string name, string value) {
            if (string.IsNullOrEmpty(value) || value.IndexOfAny(new[] { '.', '*', '>', ' ', '\t', '\r', '\n' }) >= 0) {
                throw new ArgumentException($"Subject parameter {name} is empty or contains a separator, wildcard, or whitespace.", name);
            }
        }
